class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        raise NotImplementedError("Subclasses must implement speak()")

    def describe(self):
        return f"{self.name} says {self.speak()}"

class Dog(Animal):
    def speak(self):
        return "Woof!"

class Cat(Animal):
    def speak(self):
        return "Meow!"

for animal in [Dog("Rex"), Cat("Whiskers")]:
    print(animal.describe())
# Rex says Woof!
# Whiskers says Meow!

class Employee:
    def __init__(self, name, salary):
        self.name = name
        self.salary = salary

    def annual_bonus(self):
        return self.salary * 0.05

class Manager(Employee):
    def __init__(self, name, salary, team_size):
        super().__init__(name, salary)     # delegates to Employee.__init__
        self.team_size = team_size

    def annual_bonus(self):
        base_bonus = super().annual_bonus()   # reuses parent logic, then extends it
        return base_bonus + self.team_size * 100

m = Manager("Priya", 90_000, 5)
print(m.annual_bonus())   # 90000*0.05 + 5*100 = 4500 + 500 = 5000.0

class Base:
    def __init__(self):
        self.setup()            # calls the CHILD's setup() if overridden

    def setup(self):
        pass

class Child(Base):
    def __init__(self):
        super().__init__()      # Base.__init__ → Child.setup() runs NOW
        self.items = []         # ...but items is created only AFTER

    def setup(self):
        self.items.append(1)

